#include <set>
#include <map>
#include <iostream>

int main() {
    std::multiset<int> ms = {10, 20, 20, 30};
    std::set<int> s = {10, 20};

    // Erasure in Multiset (removes duplicates)
    size_t count_multi = ms.erase(20); 
    std::cout << "Multiset erased count: " << count_multi << std::endl; // Output: 2

    // Erasure in Set (removes at most one)
    size_t count_single = s.erase(10); 
    std::cout << "Set erased count: " << count_single << std::endl; // Output: 1

    // Failed erasure
    size_t count_fail = s.erase(99);
    std::cout << "Failed erase count: " << count_fail << std::endl; // Output: 0
}
